  const keys = ['access_token','refresh_token','client_secret','authorization',
                'apikey','api_key','secret','password','token'];
  if (Array.isArray(val)) return val.map(sanitize);
  if (val && typeof val === 'object') {
    return Object.fromEntries(
      Object.entries(val).map(([k,v]) => [
        k,
        keys.includes(k.toLowerCase()) ? '[REDACTED]' : sanitize(v)
      ])
    );
  }
  return val;
}
const inData = $input.first().json;
const fbErr = inData.fb_error || {};

return [{ json: {
  scheduled_post_id: inData.scheduled_post_id,
  publication_records: [{
    platform: 'facebook',
    status: 'failed',
    success: false,
    external_post_id: null,
    external_publish_id: null,
    external_url: null,
    attempt: inData.attempt || 1,
    error_code: fbErr.error_code || 'FACEBOOK_CONFIGURATION_INCOMPLETE',
    error_message: fbErr.error_message || 'Facebook publishing failed'
  }],
  fb_response_sanitized: sanitize(fbErr)
}}];

const inData = $input.first().json || {};

return [{
  json: {
    scheduled_post_id: inData.scheduled_post_id,
    publication_records: [{
      platform: 'tiktok',
      status: 'not_configured',
      success: false,
      external_post_id: null,
      external_publish_id: null,
      external_url: null,
      attempt: inData.attempt || 1,
      error_code: 'TIKTOK_NOT_CONFIGURED',
      error_message: 'TikTok publishing is not configured'
    }]
  }
}];

const items = $input.all();
const recordsMap = new Map();

let scheduledPostId = null;

for (const item of items) {
  if (!scheduledPostId && item.json.scheduled_post_id) {
    scheduledPostId = item.json.scheduled_post_id;
  }

  const recs = item.json.publication_records;

  if (Array.isArray(recs)) {
    for (const r of recs) {
      if (r && r.platform) {
        recordsMap.set(r.platform, r);
      }
    }
  }
}

const records = Array.from(recordsMap.values());

return [{
  json: {
    scheduled_post_id: scheduledPostId,
    publication_records: records
  }
}];

const MAX_ATTEMPTS = 12;

const statusResp = $input.first().json || {};
const context = $('37 - IG Prepare Status Context').item.json;

const attempts = Number(context.ig_poll_attempts || 0) + 1;
const status = statusResp.status_code || statusResp.status || 'UNKNOWN';

const result = {
  ...context,
  ig_poll_attempts: attempts,
  ig_status: status,
  ig_status_message: statusResp.status_message || null,
  ig_media_type: statusResp.media_type || null,
  ig_permalink: statusResp.permalink || null,
  ig_media_url: statusResp.media_url || null,
  ig_timestamp: statusResp.timestamp || null
};

if (status === 'FINISHED') {
  result.ig_route = 'publish';
} else if (['ERROR','EXPIRED','REJECTED'].includes(status)) {
  result.ig_route = 'error';
  result.ig_error = {
    error_code: 'IG_STATUS_' + status,
    error_message: 'Instagram media status: ' + status +
      (statusResp.status_message ? ' - ' + statusResp.status_message : ''),
    creation_id: result.ig_creation_id,
    status
  };
} else if (attempts >= MAX_ATTEMPTS) {
  result.ig_route = 'error';
  result.ig_error = {
    error_code: 'IG_STATUS_TIMEOUT',
    error_message: 'Instagram media status did not reach FINISHED within ' +
      MAX_ATTEMPTS + ' polling attempts',
    creation_id: result.ig_creation_id,
    status
  };
} else {
  result.ig_route = 'poll_again';
}

return [{ json: result }];

