const pub = $json;
const context = $('10 - IG Poll Decision').item.json;

const record = {
  platform: 'instagram',
  status: 'published',
  success: true,
  external_post_id: pub.id || null,
  external_publish_id: context.ig_creation_id || null,
  external_url: pub.permalink || null,
  attempt: context.attempt || 1,
  error_code: null,
  error_message: null
};

return [{
  json: {
    scheduled_post_id: context.scheduled_post_id,
    publication_records: [record],
    ig_response_sanitized: sanitize(pub)
  }
}];

const auditResp = $input.first().json || {};
const input = $('35 - Platform Loop').item.json;

const accounts = auditResp.data || [];

const eligible = accounts.filter(a =>
  a.permissions &&
  a.permissions.data &&
  a.permissions.data.some(p =>
    p.permission === 'pages_manage_posts' ||
    p.permission === 'publish_pages'
  )
);

if (!eligible.length) {
  return [{
    json: {
      ...input,
      fb_route: 'error',
      fb_error: {
        error_code: 'FACEBOOK_CONFIGURATION_INCOMPLETE',
        error_message: 'Facebook publisher configuration is incomplete',
        success: false
      }
    }
  }];
}

const page = eligible[0];

return [{
  json: {
    ...input,
    fb_route: 'publish',
    fb_page_id: page.id,
    fb_page_name: page.name,
    fb_page_category: page.category || null
  }
}];

function sanitize(val) {
  const keys = ['access_token','refresh_token','client_secret','authorization',
                'apikey','api_key','secret','password','token'];
  if (Array.isArray(val)) return val.map(sanitize);
  if (val && typeof val === 'object') {
    return Object.fromEntries(
      Object.entries(val).map(([k,v]) => [
        k,
        keys.includes(k.toLowerCase()) ? '[REDACTED]' : sanitize(v)
      ])
    );
  }
  return val;
}

const createResp = $json;
const input = $('15 - FB Validate Config').item.json;

const record = {
  platform: 'facebook',
  status: createResp.id ? 'published' : 'failed',
  success: !!createResp.id,
  external_post_id: createResp.id || null,
  external_publish_id: null,
  external_url: null,
  attempt: input.attempt || 1,
  error_code: createResp.id ? null : (createResp.error ? 'FACEBOOK_POST_FAILED' : null),
  error_message: createResp.id ? null : (
    createResp.error
      ? String(createResp.error).slice(0, 500)
      : 'Facebook post creation failed'
  )
};

if (createResp.error) {
  record.success = false;
  record.error_code = 'FACEBOOK_POST_FAILED';
  record.error_message = String(createResp.error).slice(0, 500);
}

return [{
  json: {
    scheduled_post_id: input.scheduled_post_id,
    publication_records: [record],
    fb_response_sanitized: sanitize(createResp)
  }
}];

const input = $('03 - Route Input').first().json;

return [{ json: {
  scheduled_post_id: input.scheduled_post_id,
  media_type: input.media_type,
  attempt: input.attempt,
  platforms: input.platforms,
  publication_records: [{
    platform: input.platforms && input.platforms[0] || 'unknown',
    status: 'failed',
    success: false,
    external_post_id: null,
    external_publish_id: null,
    external_url: null,
    attempt: input.attempt || 1,
    error_code: 'UNSUPPORTED_MEDIA_TYPE',
    error_message: 'Media type ' + (input.media_type || 'UNKNOWN') +
      ' is not supported by WF-07. Supported: IMAGE'
  }]
}}];

const input = $('03 - Route Input').first().json;

return [{ json: {
  scheduled_post_id: input.scheduled_post_id,
  publication_records: []
}}];

const data = $input.first().json;
const platforms = Array.isArray(data.platforms) ? data.platforms : [];

return platforms.map((platform) => ({
  json: {
    ...data,
    platform
  }
}));

const data = $input.first().json;

return [{
  json: {
    scheduled_post_id: data.scheduled_post_id,
    publication_records: [{
      platform: data.platform ?? 'unknown',
      status: 'failed',
      success: false,
      external_post_id: null,
      external_publish_id: null,
      external_url: null,
      attempt: data.attempt ?? 1,
      error_code: 'UNKNOWN_PLATFORM',
      error_message: `Unsupported platform: ${data.platform ?? 'unknown'}`
    }]
  }
}];

const current = $input.first().json || {};
const base = $('35 - Platform Loop').item.json;

const creationId =
  current.ig_creation_id ||
  current.id ||
  null;

if (!creationId) {
  throw new Error('IG_MISSING_CREATION_ID');
}

return [{
  json: {
    ...base,
    ...current,
    ig_creation_id: creationId,
    ig_poll_attempts: Number(current.ig_poll_attempts || 0)
  }
}];
